  -- Adaptive upsert: copy staged rows using only the columns that exist in each real table, and fill any
  -- REQUIRED legacy column we don't stage (e.g. sellers.headquarters_city) from a sensible source.
  FOREACH pair SLICE 1 IN ARRAY ARRAY[['sellers','demo_sellers'],['certificates','demo_certificates'],['listings','demo_listings']]
  LOOP
    target := pair[1]::regclass; src := pair[2]::regclass;
    cols := ''; vals := ''; upd := '';
    SELECT coalesce(bool_or(attname = 'city'), false), coalesce(bool_or(attname = 'state'), false),
           coalesce(bool_or(attname = 'country'), false), coalesce(bool_or(attname = 'name'), false)
      INTO has_city, has_state, has_country, has_name
      FROM pg_attribute WHERE attrelid = src AND attnum > 0 AND NOT attisdropped;

    FOR r IN
      SELECT t.attname, format_type(t.atttypid, t.atttypmod) AS typ, t.attnotnull, t.atthasdef,
             (s.attname IS NOT NULL) AS staged
      FROM pg_attribute t
      LEFT JOIN pg_attribute s ON s.attrelid = src AND s.attname = t.attname AND s.attnum > 0 AND NOT s.attisdropped
      WHERE t.attrelid = target AND t.attnum > 0 AND NOT t.attisdropped AND t.attgenerated = '' AND t.attidentity = ''
      ORDER BY t.attnum
    LOOP
      IF r.staged THEN
        cols := cols || format('%I, ', r.attname);
        vals := vals || format('s.%I::%s, ', r.attname, r.typ);
        IF r.attname <> 'id' THEN upd := upd || format('%I = EXCLUDED.%I, ', r.attname, r.attname); END IF;
      ELSIF r.attnotnull AND NOT r.atthasdef THEN
        cols := cols || format('%I, ', r.attname);
        vals := vals || CASE
          WHEN r.attname ILIKE '%city%' AND has_city THEN format('s.city::%s, ', r.typ)
          WHEN r.attname ILIKE '%state%' AND has_state THEN format('s.state::%s, ', r.typ)
          WHEN r.attname ILIKE '%country%' AND has_country THEN format('s.country::%s, ', r.typ)
          WHEN r.attname ILIKE '%name%' AND has_name THEN format('s.name::%s, ', r.typ)
          WHEN r.typ = 'boolean' THEN 'false, '
          WHEN r.typ = 'uuid' THEN 'gen_random_uuid(), '
          WHEN r.typ IN ('jsonb', 'json') THEN format('%L::%s, ', '{}', r.typ)
          WHEN r.typ LIKE 'timestamp%' OR r.typ = 'date' THEN format('now()::%s, ', r.typ)
          WHEN r.typ IN ('smallint', 'integer', 'bigint', 'real', 'double precision') OR r.typ LIKE 'numeric%' THEN format('0::%s, ', r.typ)
          ELSE format('%L::%s, ', '', r.typ)
        END;
        RAISE NOTICE 'Filled required legacy column %.% automatically', target, r.attname;
      END IF;
    END LOOP;

    cols := left(cols, -2); vals := left(vals, -2); upd := left(upd, -2);
    EXECUTE format('INSERT INTO %s (%s) SELECT %s FROM %s s ON CONFLICT (id) DO UPDATE SET %s', target, cols, vals, src, upd);
    GET DIAGNOSTICS n = ROW_COUNT;
    RAISE NOTICE 'Upserted % rows into %', n, target;
  END LOOP;

  DROP TABLE demo_sellers, demo_certificates, demo_listings;
END
$do$;

-- Check: should list the 17 demo sellers with their lot counts.
SELECT s.name, s.city, s.state, s.country, count(l.id) AS lots
FROM sellers s LEFT JOIN listings l ON l.seller_id = s.id
WHERE s.id::text LIKE 'a1000000-%'
GROUP BY s.name, s.city, s.state, s.country ORDER BY s.name;
